import { randomUUID } from "node:crypto";

/**
 * UUIDs generated by Project Studio for records and operations it owns.
 *
 * This is deliberately not the type for every identifier in the system. Flue
 * owns opaque submission/conversation ids, while provider, MCP, and capability
 * ids are stable domain keys. UUIDs are for Project Studio-created identities
 * such as sessions, approvals, tasks, and idempotency requests.
 */
export type StudioUuid = string & { readonly __projectStudioUuid: unique symbol };

const UUID_V4 =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function createStudioUuid(): StudioUuid {
  return randomUUID() as StudioUuid;
}

export function isStudioUuid(value: unknown): value is StudioUuid {
  return typeof value === "string" && UUID_V4.test(value);
}
